var e={id:"alive5-send-sms",name:"Send SMS (Alive5)",icon:"sms",description:"Send an SMS through your Alive5 business number.",overview:()=>[{label:"Service",text:"Alive5 SMS"}],options:[{field:"apiKey",name:"API key",type:"string",meta:{width:"full",interface:"input",required:!0,options:{masked:!0,placeholder:"{{$env.ALIVE5_API_KEY}}"},note:"Use {{$env.ALIVE5_API_KEY}} with FLOWS_ENV_ALLOW_LIST=ALIVE5_API_KEY, or enter a key (stored in Directus)."}},{field:"channelId",name:"Channel ID",type:"string",meta:{width:"half",interface:"input",required:!0}},{field:"userId",name:"User ID",type:"string",meta:{width:"half",interface:"input",required:!0}},{field:"from",name:"From number",type:"string",meta:{width:"full",interface:"input",required:!0,options:{placeholder:"+14155550100"},note:"Alive5 business SMS number in E.164 format."}},{field:"to",name:"To number",type:"string",meta:{width:"full",interface:"input",required:!0,options:{placeholder:"{{$trigger.payload.phone}}"},note:"E.164 recipient number or a Flow data-chain expression."}},{field:"message",name:"Message",type:"text",meta:{width:"full",interface:"input-multiline",required:!0,options:{placeholder:"Hello {{$trigger.payload.name}}."},note:"SMS text. Flow expressions are resolved by Directus before execution."}}]};export{e as default};
